import {equipment,gearSlots,resolvedGearName} from './equipment.mjs';
import {ITEM_QUALITIES,ITEM_FLAWS,modifierNames} from './inventory.mjs';
import {marketCatalog,marketQuote,formatMoney} from './market.mjs';
import {derive} from './rules.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isFinite(n)?Number(n.toFixed(3)).toLocaleString():'?';
function option(value,label,current){return `<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;}
export function penaltySummary(R,s){const e=equipment(R,s),d=derive(R,s),p=e.penalties;return `<section class="load-summary" aria-label="Starting equipment effects"><div class="load-totals"><div><span>${p.complete?'Carried Enc':'Known Enc subtotal'}</span><strong>${fmt(e.total)} / ${d.capacity}</strong></div><div><span>Movement with load</span><strong>${p.complete?p.immobile?'Cannot move':p.movement:'Unresolved'}</strong></div><div><span>Agility with load</span><strong>${p.complete?p.agility:'Unresolved'}</strong></div></div><p class="small">${p.complete?p.band?`Overburdened: ${p.immobile?'unable to move':`+${p.travelFatigue} Travel Fatigue after a day’s travel; Endurance Tests to resist fatigue have Disadvantage`}.`:'Within carrying capacity.':'Resolve unknown weights or repack overflowing containers before the final load can be calculated.'} <span class="source">p. 299</span></p><div class="equipment-modifiers"><span>Stealth ${p.stealth} SL</span><span>Perception ${p.perception} SL</span>${Object.entries(d.talents.some(t=>/^(Arcane Magic|Chaos Magic|Petty Magic|Witch!)/.test(t))?p.casting:{}).map(([l,v])=>`<span>Casting / Channelling ${v} SL · ${esc(l)}</span>`).join('')}</div><p class="small muted">Armour modifiers apply to the listed tests; inherent Characteristics remain visible separately. Chamon ignores metal armour and Ghur ignores leather. <span class="source">pp. 237, 307</span></p>${e.warnings.map(w=>`<p class="packing-warning">${esc(w)}</p>`).join('')}${e.unknown.length?`<p class="packing-warning">Unresolved: ${esc(e.unknown.join('; '))}</p>`:''}</section>`;}
export function packingView(R,s){
 const eq=equipment(R,s),targets=eq.entries.filter(x=>x.capacity!==undefined),placements=(e)=>[...(e.canWear?[['worn','Worn']]:[]),['carried','Carried separately'],['stored','Stored / left behind'],...targets.filter(x=>x.key!==e.key).map((x,i)=>[x.key,`${x.name} #${eq.entries.indexOf(x)+1}${x.carrier?' · animal / vehicle':''}`])];
 const groups=[['Weapons',eq.entries.filter(x=>x.weapon)],['Armour & shields',eq.entries.filter(x=>x.armour&&!x.weapon)],['Containers & carriers',eq.entries.filter(x=>x.capacity!==undefined&&!x.weapon&&!x.armour)],['Other belongings',eq.entries.filter(x=>x.capacity===undefined&&!x.weapon&&!x.armour)]];
 return `<section class="packing section-gap"><h2>Pack your starting equipment</h2><p class="muted">Wear, carry, pack or leave items behind. Packed contents use capacity; only the pack itself counts toward your carried load. <span class="source">pp. 299, 308, 312</span></p>${penaltySummary(R,s)}<div class="field"><label for="coin-storage">Where are your coins?</label><select id="coin-storage" data-bind="coinStorage">${[['carried','Carried separately'],['stored','Stored / left behind'],...targets.map(x=>[x.key,`${x.name} #${eq.entries.indexOf(x)+1}`])].map(([v,l])=>option(v,l,s.coinStorage||'carried')).join('')}</select><small class="muted">${fmt(eq.coinEnc)} Enc at one Enc per 200 coins (p. 299). Coin totals use the displayed GC, shillings and pennies.</small></div>${groups.map(([title,entries])=>entries.length?`<details class="packing-group" ${title==='Containers & carriers'?'open':''}><summary>${title} <span class="counter">${entries.length}</span></summary>${entries.map(e=>`<div class="packing-item"><div class="packing-title"><strong>${esc(e.name)}${e.quantity>1?` ×${e.quantity}`:e.quantity===null?' · quantity unresolved':''}</strong><small>${esc(e.origin)}</small><span class="minilabel">${e.capacity!==undefined?`${fmt(e.load)} / ${e.capacity} Enc packed${e.loadUnknown?' · unknown contents':''}`:`Listed Enc ${fmt(e.enc)} · carried ${fmt(e.carriedEnc)}`}</span></div><div class="field"><label for="placement-${esc(e.key)}">Location</label><select id="placement-${esc(e.key)}" data-bind="gearPlacement" data-key="${esc(e.key)}">${placements(e).map(([v,l])=>option(v,l,e.placement)).join('')}</select></div>${e.carrier?`<div class="field"><label>Human-sized passengers, including riders</label><input type="number" min="0" step="1" data-bind="passengers" data-key="${esc(e.key)}" value="${e.passengers}" aria-label="Passengers on ${esc(e.name)}"><small class="muted">10 Enc each. The GM can adjust for other sizes (p. 299).</small></div>`:''}${e.name==='Net'?`<div class="field"><label>Net use</label><select data-bind="netMode" data-key="${esc(e.key)}" aria-label="Net use">${option('melee','Melee · Basic · Short',e.netMode)}${option('ranged','Ranged · Entangling · SB yards',e.netMode)}</select></div>`:''}${['Spear (2H)','Bastard Sword (2H)'].includes(e.weapon?.name)?`<label class="check-row"><input type="checkbox" data-bind="oneHanded" data-key="${esc(e.key)}" ${e.oneHanded?'checked':''}> Use one-handed (p. 301)</label>`:''}${e.enc===null||e.encOverride!==undefined?`<div class="field"><label>GM-confirmed Enc for an unlisted item</label><input type="number" min="0" step="0.1" data-bind="gearEnc" data-key="${esc(e.key)}" value="${e.encOverride??''}" aria-label="GM-confirmed Enc for ${esc(e.name)}"><small class="muted">Leave blank if unknown. Stored items do not add to your personal load.</small></div>`:''}${e.purchase?`<p class="small muted">${esc(modifierNames(e).join(', ')||'Standard craftsmanship')}</p>`:`<details class="item-craft"><summary>Starting-item craftsmanship <span class="source">pp. 298–299</span></summary><p class="small muted">Use only qualities or flaws your starting item actually has, agreed with your GM. Bulky normally does not apply to small trinkets.</p>${[...ITEM_QUALITIES,...ITEM_FLAWS].map(x=>`<label class="check-row"><input type="checkbox" data-bind="gearCraft" data-key="${esc(e.key)}" data-modifier="${x}" ${[...e.qualities,...e.flaws].includes(x)?'checked':''}>${x}</label>`).join('')}${['Durable','Fine'].filter(x=>e.qualities.includes(x)).map(x=>`<div class="field"><label>${x} rank</label><input type="number" min="1" step="1" data-bind="gearRank" data-key="${esc(e.key)}" data-modifier="${x}" value="${e.ranks[x]||1}" aria-label="${x} rank for ${esc(e.name)}"></div>`).join('')}</details>`}</div>`).join('')}</details>`:'').join('')}<details class="section-gap"><summary>Load and armour reference</summary><p>Above capacity: −1 Movement (minimum 3), −10 Agility, +1 Travel Fatigue. Above twice capacity: −2 Movement (minimum 2), −20 Agility (minimum 10), +2 Travel Fatigue. Above three times capacity: unable to move. Endurance Tests to resist fatigue have Disadvantage while overburdened (p. 299).</p><p>Mail and plate each impose −1 SL to Stealth. A Helm imposes −2 SL to Perception. Practical reduces armour penalties by one; Unreliable doubles them. Quick Armour replaces detailed armour and is not stacked with it (pp. 298–299, 307).</p><p>Small trinkets still need reasonable space even at Enc 0. Oversized objects normally require both hands, and only one can normally be carried. Container shapes and what fits remain subject to common sense (pp. 299, 308).</p></details></section>`;
}
export function craftsmanshipPanel(R,id,options){const item=marketCatalog(R).find(x=>x.id===id);if(!item)return '';const q=marketQuote(item,options);return `<section id="purchase-options" class="purchase-options"><h3>${esc(item.name)} · purchase options <span class="source">pp. 298–299</span></h3><p class="small muted">Each Flaw halves the listed price and improves Availability one step, except Exotic. Quality items have no fixed price multiplier in this book; use a GM-agreed final price. Durable and Fine can have multiple ranks. Lightweight reduces Enc by one; Bulky adds one. Practical reduces armour penalties by one; Unreliable doubles them. Shoddy risks breakage; Fine and Ugly affect appearance. Bulky is normally unsuitable for small trinkets.</p><div class="craft-choices">${[...ITEM_QUALITIES,...ITEM_FLAWS].map(x=>`<label class="check-row"><input type="checkbox" data-bind="marketCraft" data-modifier="${x}" ${[...(options.qualities||[]),...(options.flaws||[])].includes(x)?'checked':''}>${x}</label>`).join('')}</div>${['Durable','Fine'].filter(x=>(options.qualities||[]).includes(x)).map(x=>`<div class="field"><label>${x} rank</label><input type="number" min="1" step="1" data-bind="marketRank" data-modifier="${x}" value="${options.ranks?.[x]||1}" aria-label="${x} rank"></div>`).join('')}${q.qualities.length||!Number.isInteger(item.pennies/2**q.flaws.length)?`<div class="field"><label for="agreed-price">GM-agreed final price, in brass pennies</label><input id="agreed-price" type="number" min="0" step="1" data-bind="marketPrice" value="${options.agreedPrice??''}"><small class="muted">1 GC = 240 pennies; 1 shilling = 12 pennies.</small></div>`:''}<p>${q.error?esc(q.error):`Final price <strong>${formatMoney(q.pennies)}</strong> · ${esc(q.availability)} · ${esc(modifierNames(q).join(', ')||'Standard')}`}</p><div class="actions"><button type="button" class="primary" data-action="buy-custom-trapping" ${q.error?'disabled':''}>Buy ${esc(item.name)}</button><button type="button" class="quiet" data-action="cancel-custom-trapping">Cancel</button></div></section>`;}
export function acquisitionChoices(R,s){return gearSlots(R,s).map(x=>[x.key,`${resolvedGearName(s,x)} · ${x.origin}`]);}
